/// The seed in `level.dat` (the terrain the clients generate beyond the flat
/// area, and the nether).
const SEED: i64 = 123;
/// The flat area: chunks `-R..R` on both axes.
const R: i32 = 8;
/// The ground's top block (grass); things stand at `G + 1`.
const G: i32 = 63;
/// `LastPlayed` / region timestamps (fixed so the output is reproducible).
const CLOCK_MILLIS: i64 = 1_790_000_000_000;

// ---- disk storage ---------------------------------------------------------------------

/// A plain directory as a [`Storage`] (the client's native storage without
/// the atomic rename; this tool writes into a fresh directory).
struct DirStorage(PathBuf);

impl DirStorage {
    fn path(&self, p: &str) -> PathBuf {
        self.0.join(p)
    }
}

fn backend(e: std::io::Error) -> StorageError {
    StorageError::Backend(e.to_string())
}

impl Storage for DirStorage {
    fn read(&mut self, path: &str) -> Result<Option<Vec<u8>>, StorageError> {
        match std::fs::read(self.path(path)) {
            Ok(b) => Ok(Some(b)),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(e) => Err(backend(e)),
        }
    }
    fn write(&mut self, path: &str, bytes: &[u8]) -> Result<(), StorageError> {
        let p = self.path(path);
        if let Some(d) = p.parent() {
            std::fs::create_dir_all(d).map_err(backend)?;
        }
        std::fs::write(p, bytes).map_err(backend)
    }
    fn list(&mut self, dir: &str) -> Result<Vec<String>, StorageError> {
        let p = if dir.is_empty() {
            self.0.clone()
        } else {
            self.path(dir)
        };
        let mut v = Vec::new();
        match std::fs::read_dir(&p) {
            Ok(rd) => {
                for e in rd {
                    v.push(
                        e.map_err(backend)?
                            .file_name()
                            .to_string_lossy()
                            .into_owned(),
                    );
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err(backend(e)),
        }
        v.sort();
        Ok(v)
    }
    fn rename(&mut self, from: &str, to: &str) -> Result<(), StorageError> {
        std::fs::rename(self.path(from), self.path(to)).map_err(backend)
    }
    fn delete(&mut self, path: &str) -> Result<(), StorageError> {
        match std::fs::remove_file(self.path(path)) {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(backend(e)),
        }
    }
}

// ---- placing --------------------------------------------------------------------------

/// `setBlockAndMetadata` + the metadata forced again (module docs), then the
/// light queue drained.
fn put(w: &mut World, x: i32, y: i32, z: i32, id: i32, meta: i32) {
    w.set_block_and_metadata(x, y, z, id, meta);
    w.set_block_metadata(x, y, z, meta);
    while w.updating_lighting() {}
}

fn fill(w: &mut World, a: [i32; 3], b: [i32; 3], id: i32, meta: i32) {
    for x in a[0].min(b[0])..=a[0].max(b[0]) {
        for z in a[2].min(b[2])..=a[2].max(b[2]) {
            for y in (a[1].min(b[1])..=a[1].max(b[1])).rev() {
                put(w, x, y, z, id, meta);
            }
        }
    }
}

/// The flat ground written straight into the chunk arrays (grass at `G`,
/// dirt `G-3..G-1`, stone `G-7..G-4`, sky light 15 above the grass and 0
/// below: what `generateSkylightMap` gives for these columns).
fn flat_ground(w: &mut World) {
    for cx in -R..R {
        for cz in -R..R {
            let c = w.get_chunk_from_chunk_coords(cx, cz);
            for x in 0..16 {
                for z in 0..16 {
                    for y in 0..128 {
                        let id = match y {
                            _ if y == G => 2,
                            _ if (G - 3..G).contains(&y) => 3,
                            _ if (G - 7..G - 3).contains(&y) => 1,
                            _ => 0,
                        };
                        let i = mc_sim::world::chunk::block_index(x, y, z);
                        c.blocks[i] = id;
                        c.data.set_nibble(x, y, z, 0);
                        c.blocklight_map.set_nibble(x, y, z, 0);
                        c.skylight_map
                            .set_nibble(x, y, z, if y > G { 15 } else { 0 });
                    }
                    c.height_map[(z << 4 | x) as usize] = (G + 1) as u8;
                }
            }
            c.lowest_block_height = G + 1;
            c.is_modified = true;
        }
    }
}

// ---- views ----------------------------------------------------------------------------

#[derive(Default)]
struct Views(Vec<Value>);

impl Views {
    #[allow(clippy::too_many_arguments)]
    fn add(
        &mut self,
        name: &str,
        world: &str,
        feet: [f64; 3],
        yaw: f32,
        pitch: f32,
        time: i64,
        what: &str,
    ) {
        self.0.push(json!({
            "name": name, "world": world,
            "x": feet[0], "y": feet[1], "z": feet[2],
            "yaw": yaw, "pitch": pitch, "time": time, "what": what,
        }));
    }

    /// The last view gets extra fields for `mkviews.py` (`hotbar`: slot ->
    /// `[id, count, damage]`; `raining`: bool).
    fn extra(&mut self, key: &str, value: Value) {
        if let Some(Value::Object(m)) = self.0.last_mut() {
            m.insert(key.to_string(), value);
        }
    }
}

/// A gallery: cells along +x every `step` blocks starting at `(x0, z0)`,
/// seen from the north (the camera at `z0 - dist`, facing south, yaw 0).
struct Gallery {
    x0: i32,
    z0: i32,
    step: i32,
}

impl Gallery {
    fn cell(&self, i: i32) -> (i32, i32) {
        (self.x0 + i * self.step, self.z0)
    }
}

// Block ids used by name.
const STONE: i32 = 1;
const SAND: i32 = 12;
const GLASS: i32 = 20;
const OBSIDIAN: i32 = 49;
const FENCE: i32 = 85;
const NETHERRACK: i32 = 87;
const WATER: i32 = 9;
const LEVER: i32 = 69;

/// One gallery per row of simple cubes: `(id, meta)` placed at `G + 1`.
fn cube_gallery(w: &mut World, g: &Gallery, cells: &[(i32, i32)]) {
    for (i, &(id, meta)) in cells.iter().enumerate() {
        let (x, z) = g.cell(i as i32);
        put(w, x, G + 1, z, id, meta);
    }
}

